-- QuestAPIs v2 additive foundation. Review against the target project before applying.
create extension if not exists pgcrypto;
create type public.app_role as enum ('learner', 'developer', 'editor', 'admin');
create type public.content_status as enum ('draft', 'published', 'archived');
create type public.inventory_slot as enum ('frame', 'avatar', 'icon', 'nameplate', 'theme', 'companion', 'effect');

create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text check (char_length(display_name) between 1 and 40), role public.app_role not null default 'learner', timezone text not null default 'UTC', xp bigint not null default 0 check (xp >= 0), gold bigint not null default 0 check (gold >= 0), current_streak integer not null default 0 check (current_streak >= 0), longest_streak integer not null default 0 check (longest_streak >= 0), equipped_title_id uuid, equipped_frame_id uuid, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.regions (id uuid primary key default gen_random_uuid(), slug text unique not null, name text not null, description text not null, sort_order integer not null, status public.content_status not null default 'draft');
create table public.courses (id uuid primary key default gen_random_uuid(), slug text unique not null, region_id uuid references public.regions, name text not null, description text not null, entitlement_key text not null default 'academy.free', status public.content_status not null default 'draft');
create table public.lessons (id uuid primary key default gen_random_uuid(), slug text unique not null, course_id uuid not null references public.courses on delete cascade, title text not null, summary text not null, sort_order integer not null, status public.content_status not null default 'draft');
create table public.lesson_versions (id uuid primary key default gen_random_uuid(), lesson_id uuid not null references public.lessons on delete cascade, version integer not null, content jsonb not null, answer_key jsonb not null default '{}'::jsonb, published_at timestamptz, unique(lesson_id, version));
create table public.quest_definitions (id uuid primary key default gen_random_uuid(), lesson_id uuid references public.lessons, name text not null, objective text not null, reward_rule_key text not null, status public.content_status not null default 'draft');
create table public.attempts (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users on delete cascade, lesson_version_id uuid not null references public.lesson_versions, submitted_answers jsonb not null, score integer not null check (score between 0 and 100), accepted boolean not null, created_at timestamptz not null default now());
create table public.completions (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users on delete cascade, lesson_id uuid not null references public.lessons, attempt_id uuid not null references public.attempts, reward_version integer not null, completed_at timestamptz not null default now(), unique(user_id, lesson_id, reward_version));
create table public.level_thresholds (level integer primary key check (level > 0), cumulative_xp bigint unique not null check (cumulative_xp >= 0));
create table public.reward_rules (key text not null, version integer not null, xp integer not null default 0 check (xp >= 0), gold integer not null default 0 check (gold >= 0), active boolean not null default true, primary key(key, version));
create table public.reward_ledger (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users on delete cascade, source_type text not null, source_id text not null, idempotency_key text unique not null, rule_key text not null, rule_version integer not null, xp_delta integer not null, gold_delta integer not null, created_at timestamptz not null default now(), foreign key(rule_key, rule_version) references public.reward_rules(key, version));
create table public.achievement_definitions (id uuid primary key default gen_random_uuid(), slug text unique not null, name text not null, description text not null, criteria jsonb not null, reward_rule_key text, badge_key text, title_key text, status public.content_status not null default 'draft');
create table public.player_achievements (user_id uuid not null references auth.users on delete cascade, achievement_id uuid not null references public.achievement_definitions, unlocked_at timestamptz not null default now(), primary key(user_id, achievement_id));
create table public.title_definitions (id uuid primary key default gen_random_uuid(), slug text unique not null, name text not null, requirements jsonb not null default '{}'::jsonb);
create table public.academy_shop_items (id uuid primary key default gen_random_uuid(), slug text unique not null, name text not null, slot public.inventory_slot not null, rarity text not null, gold_price integer not null check (gold_price >= 0), requirements jsonb not null default '{}'::jsonb, status public.content_status not null default 'draft');
create table public.player_inventory (user_id uuid not null references auth.users on delete cascade, item_id uuid not null references public.academy_shop_items, acquired_at timestamptz not null default now(), primary key(user_id, item_id));
create table public.purchases (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users on delete cascade, item_id uuid not null references public.academy_shop_items, price_paid integer not null check (price_paid >= 0), ledger_id uuid unique not null references public.reward_ledger, created_at timestamptz not null default now());
create table public.learning_days (user_id uuid not null references auth.users on delete cascade, learning_date date not null, created_at timestamptz not null default now(), primary key(user_id, learning_date));
create table public.plans (id uuid primary key default gen_random_uuid(), key text unique not null, name text not null, active boolean not null default false, stripe_price_id text unique);
create table public.entitlement_definitions (key text primary key, description text not null, value_kind text not null check (value_kind in ('boolean','integer','json')));
create table public.plan_entitlements (plan_id uuid not null references public.plans on delete cascade, entitlement_key text not null references public.entitlement_definitions, value jsonb not null, primary key(plan_id, entitlement_key));
create table public.subscriptions (user_id uuid primary key references auth.users on delete cascade, plan_id uuid references public.plans, provider_customer_id text unique, provider_subscription_id text unique, status text not null, period_end timestamptz, updated_at timestamptz not null default now());
create table public.user_grants (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users on delete cascade, entitlement_key text not null references public.entitlement_definitions, value jsonb not null, source text not null, starts_at timestamptz not null default now(), expires_at timestamptz);
create table public.promotion_definitions (id uuid primary key default gen_random_uuid(), key text unique not null, promotion_type text not null, configuration jsonb not null, eligibility jsonb not null, starts_at timestamptz, ends_at timestamptz, active boolean not null default false);
create table public.promotion_redemptions (promotion_id uuid not null references public.promotion_definitions, user_id uuid not null references auth.users on delete cascade, grant_id uuid references public.user_grants, redeemed_at timestamptz not null default now(), primary key(promotion_id, user_id));
create table public.api_products (id uuid primary key default gen_random_uuid(), slug text unique not null, name text not null, status text not null, description text not null);
create table public.api_versions (id uuid primary key default gen_random_uuid(), product_id uuid not null references public.api_products on delete cascade, version text not null, base_path text not null, active boolean not null default false, unique(product_id, version));
create table public.developer_api_keys (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users on delete cascade, name text not null, key_prefix text not null, key_hash text unique not null, last_used_at timestamptz, revoked_at timestamptz, created_at timestamptz not null default now());
create table public.api_usage (id bigint generated always as identity primary key, key_id uuid not null references public.developer_api_keys, product_id uuid not null references public.api_products, occurred_at timestamptz not null default now(), status_code integer not null, units integer not null default 1 check (units > 0), latency_ms integer, request_id uuid not null default gen_random_uuid());
create index api_usage_meter_idx on public.api_usage(key_id, product_id, occurred_at desc);
create table public.api_quota_windows (key_id uuid not null references public.developer_api_keys, product_id uuid not null references public.api_products, window_start timestamptz not null, used integer not null default 0 check (used >= 0), primary key(key_id, product_id, window_start));
create table public.notifications (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users on delete cascade, kind text not null, title text not null, body text not null, read_at timestamptz, created_at timestamptz not null default now());
create table public.feedback (id uuid primary key default gen_random_uuid(), user_id uuid references auth.users on delete set null, email text, category text not null, body text not null, status text not null default 'new', created_at timestamptz not null default now());
create table public.event_outbox (id uuid primary key default gen_random_uuid(), event_type text not null, aggregate_id text not null, payload jsonb not null, created_at timestamptz not null default now(), processed_at timestamptz);
alter table public.profiles add constraint profiles_equipped_title_fk foreign key (equipped_title_id) references public.title_definitions;
alter table public.profiles add constraint profiles_equipped_frame_fk foreign key (equipped_frame_id) references public.academy_shop_items;

alter table public.profiles enable row level security; alter table public.attempts enable row level security; alter table public.completions enable row level security; alter table public.reward_ledger enable row level security; alter table public.player_achievements enable row level security; alter table public.player_inventory enable row level security; alter table public.purchases enable row level security; alter table public.learning_days enable row level security; alter table public.subscriptions enable row level security; alter table public.user_grants enable row level security; alter table public.developer_api_keys enable row level security; alter table public.api_usage enable row level security; alter table public.notifications enable row level security;
create policy "profiles are self readable" on public.profiles for select using (auth.uid() = id);
create policy "attempts are self readable" on public.attempts for select using (auth.uid() = user_id);
create policy "completions are self readable" on public.completions for select using (auth.uid() = user_id);
create policy "ledger is self readable" on public.reward_ledger for select using (auth.uid() = user_id);
create policy "achievements are self readable" on public.player_achievements for select using (auth.uid() = user_id);
create policy "inventory is self readable" on public.player_inventory for select using (auth.uid() = user_id);
create policy "purchases are self readable" on public.purchases for select using (auth.uid() = user_id);
create policy "learning days are self readable" on public.learning_days for select using (auth.uid() = user_id);
create policy "subscriptions are self readable" on public.subscriptions for select using (auth.uid() = user_id);
create policy "grants are self readable" on public.user_grants for select using (auth.uid() = user_id);
create policy "keys are self readable" on public.developer_api_keys for select using (auth.uid() = user_id);
create policy "usage is self readable" on public.api_usage for select using (exists (select 1 from public.developer_api_keys k where k.id = key_id and k.user_id = auth.uid()));
create policy "notifications are self readable" on public.notifications for select using (auth.uid() = user_id);
-- No client mutation policies exist for authority-bearing tables. Mutations use reviewed server transactions.
